head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > oncelldblclick]<br/>Body Cell 영역을 마우스 왼쪽 버튼으로 더블 클릭할 때 발생합니다.",
    "validation" : [
        "DataList 와 바인딩 되지 않은 Cell 에서도 oncelldblclick 이벤트가 발생합니다.",
        "숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "사용자에 의해 Column 의 순서가 변경되어도 Column 의 인덱스값은 변경되지 않습니다.",
        "RowNum, RowStatus Column 은 인덱스에 포함되지 않습니다.",
        "oncellclick 이벤트가 두 번 발생한 후 oncelldblclick 이벤트가 발생합니다.",
        "DataList 와 바인딩 되지 않은 Cell 인 경우 oncelldblclick 이벤트만 발생합니다.",
        "컴포넌트 또는 Cell 이 비활성화(disabled) 상태이면 이벤트가 발생하지 않습니다.",
        "Body Cell 이 편집 모드 상태일때 편집 영역을 더블 클릭하면 oneditdblclick > oncelldblclick 순서로 이벤트가 발생하며 oncellclick 이벤트는 발생하지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - 그리드 직접 구성 (oncelldblclick caveat 전수 검증용)
//    · rowNumVisible / rowStatusVisible = true → RowNum, RowStatus 는 columnIndex 미포함 확인
//    · column2(인덱스 1) 는 setColumnVisible(1,false) 로 숨김 → 숨김 Column 도 인덱스 포함 확인
//    · column4(id="unbound", 인덱스 3) 는 DataList 미바인딩 Cell → oncelldblclick 만 발생 확인
//    · column1(인덱스 0) 는 editType=text 편집 가능 → 편집 모드 더블클릭 시 oneditdblclick > oncelldblclick 확인
//    · (0,0) Cell 은 setCellDisabled 로 비활성화 → 이벤트 미발생 확인
//  - oncellclick / oncelldblclick / oneditdblclick 핸들러는 발생 즉시 한 줄 출력(출력 순서 = 발생 순서)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="RowNum/RowStatus 표시(인덱스 미포함) / 인덱스1(name2) 숨김(인덱스 포함) / 인덱스3(unbound) DataList 미바인딩 / 인덱스0(name1) 편집가능 / 인덱스4(버튼) button 타입 / (0,0) Cell disabled. 셀 더블클릭(편집 가능셀은 더블클릭으로 편집 진입 후 다시 더블클릭) 시 하단 출력 순서 확인"', '', 'label1');
    $c.gcm.createLabel('label="[엔진 실제 동작] 더블클릭 시 oncellclick 발생 횟수는 셀 타입에 따라 다릅니다 — 일반(text) Cell 은 1회(2번째 클릭은 셀 포커스 경로에서 억제), button 타입 Cell(인덱스4)은 버튼 자체 onclick 으로 2회 발생 후 oncelldblclick 이 발생합니다. 즉 @spec 의 oncellclick 두 번 은 button Cell 에서 성립. 단 미바인딩 Cell(text)도 oncellclick 1회 후 oncelldblclick 발생(@spec 의 미바인딩 시 oncelldblclick 만 발생 과는 다름)."', '', 'label2');

    // DataList 생성 (column4=unbound 는 의도적으로 미바인딩)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { col1 : "disabled", col2 : "B0", col3 : "C0" },
        { col1 : "A1", col2 : "B1", col3 : "C1" },
        { col1 : "A2", col2 : "B2", col3 : "C2" },
        { col1 : "A3", col2 : "B3", col3 : "C3" }
    ]);

    // target 그리드 직접 구성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" rowNumVisible="true" rowStatusVisible="true" rowNumHeaderValue="No." rowStatusHeaderValue="St." checkAllType="false" ev:oncellclick="scwin.target1_oncellclick" ev:oncelldblclick="scwin.target1_oncelldblclick" ev:oneditdblclick="scwin.target1_oneditdblclick" id="" style="width:620px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="oncelldblclick test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1(idx0,편집가능)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2(idx1,숨김)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3(idx2)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="unbound(idx3,미바인딩)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column5" value="버튼(idx4)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="unbound"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="button" id="btnCol" value="버튼"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 인덱스 1 (column2 / col2) 숨김 → 숨김 Column 도 인덱스에 포함됨을 검증
    target1.setColumnVisible(1, false);

    // (0,0) Cell 비활성화 → 더블 클릭 시 이벤트 미발생 검증
    target1.setCellDisabled(0, "col1", true);
}



// "Column 순서 변경" 버튼 : 인덱스 2(col3) 와 인덱스 3(unbound) 의 표시 순서를 바꿈
//  - 순서가 바뀌어도 columnIndex 값은 변경되지 않음을 더블클릭으로 확인
scwin.btn_setColumnOrder_onclick = function (e) {
    target1.setColumnOrder(["unbound", "col3"]);
    wf_body_bottom.getObj("scwin").setReturnValue("표시 순서 변경 완료 (col3 <-> unbound). 더블클릭 시 columnIndex 는 불변인지 확인");
};



scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncellclick > rowIndex:" + rowIndex + ", columnIndex:" + columnIndex + ", columnId:" + columnId);
}



scwin.target1_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    wf_body_bottom.getObj("scwin").setReturnValue("oncelldblclick > rowIndex:" + rowIndex + ", columnIndex:" + columnIndex + ", columnId:" + columnId);
}



scwin.target1_oneditdblclick = function (rowIndex, columnIndex, columnId) {
    wf_body_bottom.getObj("scwin").setReturnValue("oneditdblclick > rowIndex:" + rowIndex + ", columnIndex:" + columnIndex + ", columnId:" + columnId);
}
